"use client";

import React, { useState, useMemo, useRef } from "react";
import { 
  Calendar as CalendarIcon, 
  ChevronRight, 
  CheckCircle2, 
  AlertTriangle, 
  Clock, 
  UploadCloud, 
  Plane, 
  Stethoscope, 
  Briefcase, 
  Baby, 
  Umbrella, 
  GraduationCap, 
  Heart, 
  AlertOctagon,
  UserCheck
} from "lucide-react";

// --- CONFIGURATION ---
const HOLIDAYS = [
  { date: "2026-01-26", name: "Republic Day" }
];

const LEAVE_TYPES = [
  { id: "annual", label: "Annual", icon: Plane, balance: 18, color: "text-blue-600 dark:text-blue-400", bg: "bg-blue-50 dark:bg-blue-900/20", policy: "Vacation" },
  { id: "sick", label: "Sick", icon: Stethoscope, balance: 12, color: "text-rose-600 dark:text-rose-400", bg: "bg-rose-50 dark:bg-rose-900/20", policy: "Medical", requiresDoc: true },
  { id: "casual", label: "Casual", icon: Briefcase, balance: 6, color: "text-amber-600 dark:text-amber-400", bg: "bg-amber-50 dark:bg-amber-900/20", policy: "Personal" },
  { id: "comp_off", label: "Comp Off", icon: Umbrella, balance: 3, color: "text-emerald-600 dark:text-emerald-400", bg: "bg-emerald-50 dark:bg-emerald-900/20", policy: "Overtime" },
  { id: "maternity", label: "Maternity", icon: Baby, balance: 90, color: "text-purple-600 dark:text-purple-400", bg: "bg-purple-50 dark:bg-purple-900/20", policy: "Parental", requiresDoc: true },
  { id: "bereavement", label: "Bereavement", icon: Heart, balance: 5, color: "text-slate-600 dark:text-slate-400", bg: "bg-slate-100 dark:bg-slate-800", policy: "Family" },
  { id: "study", label: "Study", icon: GraduationCap, balance: 0, color: "text-indigo-600 dark:text-indigo-400", bg: "bg-indigo-50 dark:bg-indigo-900/20", policy: "Edu" },
  { id: "unpaid", label: "L.O.P", icon: AlertOctagon, balance: 0, color: "text-red-600 dark:text-red-400", bg: "bg-red-50 dark:bg-red-900/20", policy: "Unpaid" },
];

const TEAM_GANTT = [
  { id: 1, name: "Sarah Jenkins", role: "Manager", start: 20, end: 22, avatar: "SJ", color: "bg-purple-500" },
  { id: 2, name: "Mike Ross", role: "Backend", start: 12, end: 15, avatar: "MR", color: "bg-orange-500" },
  { id: 3, name: "Jessica P.", role: "Design", start: 26, end: 27, avatar: "JP", color: "bg-blue-500" },
];

export default function ExecutiveAbsencePortal() {
  // --- STATE ---
  const [mode, setMode] = useState<"range" | "single">("range");
  const [range, setRange] = useState<{ start: string; end: string }>({ start: "", end: "" });
  const [typeId, setTypeId] = useState("annual");
  const [reason, setReason] = useState("");
  const [halfDay, setHalfDay] = useState<"am" | "pm" | null>(null);
  const [file, setFile] = useState<File | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // --- LOGIC ---
  const handleDateClick = (dateStr: string) => {
    if (mode === "single") {
      setRange({ start: dateStr, end: dateStr });
      setHalfDay(null);
    } else {
      if (!range.start || (range.start && range.end)) {
        setRange({ start: dateStr, end: "" });
      } else {
        const s = new Date(range.start);
        const e = new Date(dateStr);
        if (e < s) setRange({ start: dateStr, end: "" });
        else setRange({ ...range, end: dateStr });
      }
    }
  };

  const stats = useMemo(() => {
    if (!range.start || !range.end) return { days: 0, deduction: 0, conflict: false };
    
    let deduction = 0;
    let conflict = false;
    let cur = new Date(range.start);
    let end = new Date(range.end);
    let days = 0;

    while (cur <= end) {
      const dateStr = cur.toISOString().split('T')[0];
      const isHoliday = HOLIDAYS.some(h => h.date === dateStr);
      const isWeekend = cur.getDay() === 0 || cur.getDay() === 6;

      if (!isHoliday && !isWeekend) {
        deduction += (range.start === range.end && halfDay) ? 0.5 : 1;
        
        // Check Team Conflict
        const dayNum = cur.getDate();
        if (TEAM_GANTT.some(p => dayNum >= p.start && dayNum <= p.end)) {
            conflict = true;
        }
      }
      days++;
      cur.setDate(cur.getDate() + 1);
    }
    return { days, deduction, conflict };
  }, [range, halfDay]);

  const selectedType = LEAVE_TYPES.find(t => t.id === typeId)!;

  return (
    // MAIN CONTAINER: Handles Dark Mode Background & Text
    <div className="flex h-screen w-full bg-[#F2F4F7] dark:bg-black font-sans text-slate-800 dark:text-slate-100 overflow-hidden transition-colors duration-200">
      
      {/* --- LEFT PANE: VISUAL CONTEXT (70%) --- */}
      <div className="flex-1 flex flex-col p-6 pr-3 gap-6 overflow-hidden">
        
        {/* HEADER */}
        <div className="flex items-center justify-between">
           <div>
              <h1 className="text-2xl font-bold text-slate-900 dark:text-white">Absence Management</h1>
              <p className="text-xs font-medium text-slate-500 dark:text-slate-400">Engineering Team • Hyderabad</p>
           </div>
           
           {/* MODE SWITCHER: Dark Mode Compatible */}
           <div className="bg-white dark:bg-slate-900 p-1 rounded-xl shadow-sm border border-slate-200 dark:border-slate-800 flex">
              <button 
                onClick={() => { setMode("single"); setRange({start:"", end:""}); }}
                className={`px-4 py-2 rounded-lg text-xs font-bold transition-all ${
                  mode === "single" 
                  ? "bg-slate-900 dark:bg-blue-600 text-white shadow" 
                  : "text-slate-500 dark:text-slate-400 hover:bg-slate-50 dark:hover:bg-slate-800"
                }`}
              >
                Single Day
              </button>
              <button 
                onClick={() => { setMode("range"); setRange({start:"", end:""}); }}
                className={`px-4 py-2 rounded-lg text-xs font-bold transition-all ${
                  mode === "range" 
                  ? "bg-slate-900 dark:bg-blue-600 text-white shadow" 
                  : "text-slate-500 dark:text-slate-400 hover:bg-slate-50 dark:hover:bg-slate-800"
                }`}
              >
                Date Range
              </button>
           </div>
        </div>

        {/* CALENDAR CANVAS */}
        <div className="flex-1 bg-white dark:bg-slate-900 rounded-3xl border border-slate-200 dark:border-slate-800 shadow-sm flex flex-col overflow-hidden relative">
           
           {/* Calendar Header */}
           <div className="flex items-center justify-between px-8 py-6 border-b border-slate-100 dark:border-slate-800">
              <h2 className="text-xl font-bold text-slate-800 dark:text-white">January 2026</h2>
              <div className="flex gap-6 text-[10px] font-bold uppercase tracking-widest text-slate-400 dark:text-slate-500">
                 <div className="flex items-center gap-2"><span className="w-2 h-2 rounded-full bg-slate-900 dark:bg-blue-500"/>Selected</div>
                 <div className="flex items-center gap-2"><span className="w-2 h-2 rounded-full bg-rose-500"/>Holiday</div>
                 <div className="flex items-center gap-2"><span className="w-2 h-2 rounded-full bg-slate-200 dark:bg-slate-700"/>Weekend</div>
              </div>
           </div>

           {/* The Grid */}
           <div className="flex-1 p-8 overflow-y-auto">
              <div className="grid grid-cols-7 gap-3 h-full content-start">
                 {['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'].map(d => (
                    <div key={d} className="text-center text-[10px] font-black text-slate-300 dark:text-slate-600 uppercase mb-2">{d}</div>
                 ))}
                 
                 {[null, null, null].map((_, i) => <div key={`e-${i}`}/>)}

                 {Array.from({ length: 31 }).map((_, i) => {
                    const day = i + 1;
                    const dateStr = `2026-01-${day < 10 ? `0${day}` : day}`;
                    const holiday = HOLIDAYS.find(h => h.date === dateStr);
                    const isWeekend = new Date(2026, 0, day).getDay() % 6 === 0;
                    const isSelected = range.start === dateStr || range.end === dateStr;
                    const inRange = range.start && range.end && dateStr > range.start && dateStr < range.end;

                    return (
                       <button
                         key={day}
                         onClick={() => handleDateClick(dateStr)}
                         className={`
                           relative h-20 rounded-2xl border text-left p-3 transition-all group
                           ${isSelected 
                             ? "bg-slate-900 dark:bg-blue-600 text-white border-slate-900 dark:border-blue-600 shadow-xl scale-105 z-10" 
                             : ""}
                           ${inRange 
                             ? "bg-blue-50 dark:bg-blue-900/30 text-blue-700 dark:text-blue-100 border-blue-100 dark:border-blue-800" 
                             : ""}
                           ${!isSelected && !inRange && holiday 
                             ? "bg-rose-50 dark:bg-rose-900/20 border-rose-100 dark:border-rose-900/50" 
                             : ""}
                           ${!isSelected && !inRange && isWeekend 
                             ? "bg-slate-50 dark:bg-slate-800/50 border-transparent text-slate-300 dark:text-slate-600" 
                             : "bg-white dark:bg-slate-900 border-slate-100 dark:border-slate-800 hover:border-blue-400 dark:hover:border-blue-500"}
                         `}
                       >
                          <span className="text-sm font-bold">{day}</span>
                          {holiday && <span className={`absolute bottom-2 left-2 text-[9px] font-bold px-1.5 py-0.5 rounded ${isSelected ? "bg-white/20 text-white" : "bg-rose-100 dark:bg-rose-900/40 text-rose-600 dark:text-rose-300"}`}>{holiday.name}</span>}
                       </button>
                    )
                 })}
              </div>
           </div>
        </div>

        {/* TEAM TIMELINE (Gantt View) */}
        <div className="h-32 bg-white dark:bg-slate-900 rounded-3xl border border-slate-200 dark:border-slate-800 shadow-sm p-5 flex flex-col shrink-0">
           <div className="flex items-center justify-between mb-2">
              <h3 className="text-xs font-bold uppercase text-slate-400 dark:text-slate-500">Team Schedule (January)</h3>
              <div className="text-[10px] font-bold bg-slate-100 dark:bg-slate-800 px-2 py-1 rounded text-slate-500 dark:text-slate-400">3 Members Out</div>
           </div>
           
           <div className="flex-1 relative mt-2">
              {/* Day Markers */}
              <div className="absolute top-0 bottom-0 left-0 right-0 flex justify-between opacity-10 pointer-events-none">
                 {Array.from({length: 31}).map((_, i) => <div key={i} className="w-px bg-slate-900 dark:bg-white h-full"/>)}
              </div>
              
              {/* Bars */}
              <div className="space-y-2 relative z-10">
                 {TEAM_GANTT.map(person => (
                    <div key={person.id} className="flex items-center">
                       <div className="w-32 shrink-0 flex items-center gap-2">
                          <div className="h-6 w-6 rounded-full bg-slate-100 dark:bg-slate-800 text-[9px] font-bold flex items-center justify-center border border-slate-200 dark:border-slate-700 text-slate-600 dark:text-slate-300">{person.avatar}</div>
                          <span className="text-[10px] font-bold text-slate-600 dark:text-slate-300 truncate">{person.name}</span>
                       </div>
                       <div className="flex-1 h-6 relative">
                          <div 
                             className={`absolute top-0 bottom-0 rounded-md shadow-sm ${person.color} opacity-80`}
                             style={{ left: `${(person.start / 31) * 100}%`, width: `${((person.end - person.start) / 31) * 100}%` }}
                          />
                       </div>
                    </div>
                 ))}
              </div>
           </div>
        </div>

      </div>

      {/* --- RIGHT PANE: CONTROL PANEL (30%) --- */}
      <div className="w-[400px] flex-none bg-white dark:bg-slate-900 border-l border-slate-200 dark:border-slate-800 flex flex-col h-full shadow-2xl z-20">
         
         {/* 1. STATUS CARD */}
         <div className="p-6 border-b border-slate-100 dark:border-slate-800 bg-slate-50/50 dark:bg-slate-950/30">
            <div className="flex items-center justify-between mb-4">
               <span className="text-[10px] font-bold uppercase tracking-widest text-slate-400 dark:text-slate-500">Request Impact</span>
               {stats.conflict ? (
                 <span className="flex items-center gap-1 text-[10px] font-bold text-amber-600 dark:text-amber-400 bg-amber-100 dark:bg-amber-900/30 px-2 py-1 rounded-full animate-pulse">
                    <AlertTriangle className="h-3 w-3" /> Team Conflict
                 </span>
               ) : (
                 <span className="flex items-center gap-1 text-[10px] font-bold text-emerald-600 dark:text-emerald-400 bg-emerald-100 dark:bg-emerald-900/30 px-2 py-1 rounded-full">
                    <CheckCircle2 className="h-3 w-3" /> Team Clear
                 </span>
               )}
            </div>
            
            <div className="bg-white dark:bg-slate-800 rounded-xl border border-slate-200 dark:border-slate-700 p-4 shadow-sm">
               <div className="flex justify-between items-center mb-1">
                  <span className="text-xs text-slate-500 dark:text-slate-400">Deduction</span>
                  <span className="text-2xl font-black text-slate-900 dark:text-white">{stats.deduction}<span className="text-sm font-medium text-slate-400 dark:text-slate-500 ml-1">Days</span></span>
               </div>
               <div className="w-full bg-slate-100 dark:bg-slate-700 h-1.5 rounded-full overflow-hidden flex mt-2">
                  <div className={`h-full ${selectedType.color.replace('text-', 'bg-').split(' ')[0]} opacity-30`} style={{ width: '60%' }}/>
                  <div className="h-full bg-rose-500" style={{ width: `${(stats.deduction / 20) * 100}%` }}/>
               </div>
               <div className="flex justify-between mt-2 text-[10px] font-bold text-slate-400 dark:text-slate-500">
                  <span>Balance: {selectedType.balance}</span>
                  <span className="text-rose-500 dark:text-rose-400">After: {selectedType.balance - stats.deduction}</span>
               </div>
            </div>
         </div>

         {/* 2. FORM SCROLL AREA */}
         <div className="flex-1 overflow-y-auto p-6 space-y-6">
            
            {/* Leave Type Grid */}
            <div>
               <label className="text-[10px] font-bold uppercase text-slate-400 dark:text-slate-500 mb-3 block">Select Type</label>
               <div className="grid grid-cols-2 gap-2">
                  {LEAVE_TYPES.map(t => (
                     <button
                       key={t.id}
                       onClick={() => setTypeId(t.id)}
                       className={`flex items-center gap-2 p-2 rounded-lg border text-left transition-all ${
                          typeId === t.id 
                          ? "bg-slate-900 dark:bg-blue-600 border-slate-900 dark:border-blue-600 text-white shadow-md" 
                          : "bg-white dark:bg-slate-900 border-slate-200 dark:border-slate-700 text-slate-600 dark:text-slate-300 hover:bg-slate-50 dark:hover:bg-slate-800"
                       }`}
                     >
                        <t.icon className={`h-4 w-4 ${typeId === t.id ? "text-white" : t.color}`} />
                        <span className="text-xs font-bold truncate">{t.label}</span>
                     </button>
                  ))}
               </div>
            </div>

            {/* Half Day Toggle */}
            {mode === "single" && range.start && (
               <div className="animate-in slide-in-from-top-2">
                  <label className="text-[10px] font-bold uppercase text-slate-400 dark:text-slate-500 mb-2 block">Duration</label>
                  <div className="grid grid-cols-3 gap-2 bg-slate-100 dark:bg-slate-800 p-1 rounded-lg">
                     <button onClick={() => setHalfDay(null)} className={`text-[10px] font-bold py-2 rounded ${!halfDay ? "bg-white dark:bg-slate-600 shadow text-slate-900 dark:text-white" : "text-slate-400 dark:text-slate-500"}`}>Full Day</button>
                     <button onClick={() => setHalfDay("am")} className={`text-[10px] font-bold py-2 rounded ${halfDay === "am" ? "bg-white dark:bg-slate-600 shadow text-slate-900 dark:text-white" : "text-slate-400 dark:text-slate-500"}`}>1st Half</button>
                     <button onClick={() => setHalfDay("pm")} className={`text-[10px] font-bold py-2 rounded ${halfDay === "pm" ? "bg-white dark:bg-slate-600 shadow text-slate-900 dark:text-white" : "text-slate-400 dark:text-slate-500"}`}>2nd Half</button>
                  </div>
               </div>
            )}

            {/* Reason */}
            <div>
               <label className="text-[10px] font-bold uppercase text-slate-400 dark:text-slate-500 mb-2 block">Reason</label>
               <textarea 
                  className="w-full h-24 rounded-xl border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-950 p-3 text-xs font-medium text-slate-900 dark:text-white focus:ring-2 focus:ring-slate-900 dark:focus:ring-blue-500 outline-none resize-none"
                  placeholder="Enter details..."
                  value={reason}
                  onChange={(e) => setReason(e.target.value)}
               />
            </div>

            {/* File Upload */}
            {selectedType.requiresDoc && (
               <div className="animate-in zoom-in-95">
                  <label className="text-[10px] font-bold uppercase text-slate-400 dark:text-slate-500 mb-2 block flex justify-between">
                     <span>Attachment</span> <span className="text-rose-500 dark:text-rose-400">* Required</span>
                  </label>
                  <div 
                     onClick={() => fileInputRef.current?.click()}
                     className={`border-2 border-dashed rounded-xl h-16 flex items-center justify-center cursor-pointer transition-colors gap-2 ${
                        file 
                        ? "border-emerald-500 bg-emerald-50 dark:bg-emerald-900/20" 
                        : "border-slate-200 dark:border-slate-700 hover:border-blue-400 dark:hover:border-blue-500 hover:bg-slate-50 dark:hover:bg-slate-800"
                     }`}
                  >
                     <input type="file" className="hidden" ref={fileInputRef} onChange={(e) => e.target.files && setFile(e.target.files[0])} />
                     {file ? (
                        <span className="text-xs font-bold text-emerald-600 dark:text-emerald-400 flex items-center gap-1"><CheckCircle2 className="h-4 w-4"/> {file.name}</span>
                     ) : (
                        <div className="flex flex-col items-center gap-1 text-slate-400 dark:text-slate-500">
                           <UploadCloud className="h-4 w-4" />
                           <span className="text-[9px] font-bold">Upload Document</span>
                        </div>
                     )}
                  </div>
               </div>
            )}

            {/* Approver Info */}
            <div className="bg-slate-50 dark:bg-slate-800/50 rounded-xl p-3 flex items-center gap-3 border border-slate-100 dark:border-slate-700">
               <div className="h-8 w-8 rounded-full bg-white dark:bg-slate-700 border border-slate-200 dark:border-slate-600 flex items-center justify-center text-xs font-bold text-slate-700 dark:text-slate-300">SJ</div>
               <div>
                  <p className="text-[10px] font-bold uppercase text-slate-400 dark:text-slate-500">Approver</p>
                  <p className="text-xs font-bold text-slate-900 dark:text-white">Sarah Jenkins</p>
               </div>
               <div className="ml-auto flex items-center gap-1 text-[10px] font-bold text-slate-400 dark:text-slate-500 bg-white dark:bg-slate-900 px-2 py-1 rounded border border-slate-100 dark:border-slate-700">
                  <Clock className="h-3 w-3" /> ~4h
               </div>
            </div>

         </div>

         {/* 3. SUBMIT BUTTON */}
         <div className="p-6 border-t border-slate-100 dark:border-slate-800 bg-slate-50 dark:bg-slate-950/30">
            <button 
               disabled={!range.start || (selectedType.requiresDoc && !file)}
               className="w-full bg-slate-900 dark:bg-blue-600 text-white py-4 rounded-xl font-bold text-sm shadow-lg hover:bg-black dark:hover:bg-blue-500 disabled:bg-slate-300 dark:disabled:bg-slate-800 dark:disabled:text-slate-500 transition-all flex items-center justify-center gap-2"
            >
               {range.start ? "Submit Request" : "Select Dates"}
               {range.start && <ChevronRight className="h-4 w-4" />}
            </button>
         </div>

      </div>
    </div>
  );
}